-- Function mode for the built-in write-code problems: students write only solve(...)
-- (generated from tools/signatures.py; starters are checked by tools/check_starters.py)
ALTER TABLE challenges ADD COLUMN signature TEXT;
UPDATE challenges SET signature = '{"read": [{"n": "n", "t": "int", "hide": true}, {"n": "a", "t": "int[]", "len": "n"}], "args": ["a"], "ret": "int", "doc": {"en": "`a` is the list of integers. Return the second largest distinct value, or -1.", "fr": "`a` est la liste d''entiers. Retourne la deuxième plus grande valeur distincte, ou -1."}}' WHERE source = 'seed' AND test_set = 'second-largest';
UPDATE challenges SET signature = '{"read": [{"n": "s", "t": "str"}], "args": ["s"], "ret": "str", "doc": {"en": "`s` is the string. Return the encoded string (for example `\"a3b1\"`).", "fr": "`s` est la chaîne. Retourne la chaîne encodée (par exemple `\"a3b1\"`)."}}' WHERE source = 'seed' AND test_set = 'run-length';
UPDATE challenges SET signature = '{"read": [{"n": "q", "t": "int", "hide": true}, {"n": "strings", "t": "str[]", "len": "q"}], "args": ["strings"], "ret": "str[]", "doc": {"en": "`strings` is the list of bracket strings. Return a list with `\"YES\"` or `\"NO\"` for each one, in order.", "fr": "`strings` est la liste des chaînes de parenthèses. Retourne une liste avec `\"YES\"` ou `\"NO\"` pour chacune, dans l''ordre."}}' WHERE source = 'seed' AND test_set = 'balanced-brackets';
UPDATE challenges SET signature = '{"read": [{"n": "n", "t": "int", "hide": true}, {"n": "a", "t": "int[]", "len": "n"}], "args": ["a"], "ret": "int[]", "doc": {"en": "`a` is the list. Return two numbers: `[length, value]` of the longest plateau.", "fr": "`a` est la liste. Retourne deux nombres : `[longueur, valeur]` du plus long plateau."}}' WHERE source = 'seed' AND test_set = 'longest-plateau';
UPDATE challenges SET signature = '{"read": [{"n": "n", "t": "int", "hide": true}, {"n": "words", "t": "str[]", "len": "n"}], "args": ["words"], "ret": "int[]", "doc": {"en": "`words` is the list of words. Return two numbers: `[number of families, size of the largest]`.", "fr": "`words` est la liste des mots. Retourne deux nombres : `[nombre de familles, taille de la plus grande]`."}}' WHERE source = 'seed' AND test_set = 'anagram-groups';
UPDATE challenges SET signature = '{"read": [{"n": "number", "t": "str"}], "args": ["number"], "ret": "int[]", "doc": {"en": "`number` is given as a **string** (it can have thousands of digits). Return two numbers: `[rounds, final digit]`.", "fr": "`number` est donné sous forme de **chaîne** (il peut avoir des milliers de chiffres). Retourne deux nombres : `[tours, chiffre final]`."}}' WHERE source = 'seed' AND test_set = 'digit-rounds';
UPDATE challenges SET signature = '{"read": [{"n": "n", "t": "int", "hide": true}, {"n": "k", "t": "int"}, {"n": "a", "t": "int[]", "len": "n"}], "args": ["a", "k"], "ret": "int", "doc": {"en": "`a` is the list, `k` the target sum. Return the number of subarrays whose sum is exactly `k`.", "fr": "`a` est la liste, `k` la somme visée. Retourne le nombre de sous-tableaux dont la somme vaut exactement `k`."}}' WHERE source = 'seed' AND test_set = 'subarray-sum-k';
UPDATE challenges SET signature = '{"read": [{"n": "s", "t": "str"}], "args": ["s"], "ret": "int", "doc": {"en": "`s` is the string. Return the length of the longest substring without repeated characters.", "fr": "`s` est la chaîne. Retourne la longueur de la plus longue sous-chaîne sans caractère répété."}}' WHERE source = 'seed' AND test_set = 'longest-unique';
UPDATE challenges SET signature = '{"read": [{"n": "n", "t": "int", "hide": true}, {"n": "segments", "t": "int[][]", "len": "n", "cols": 2}], "args": ["segments"], "ret": "int", "doc": {"en": "`segments` is a list of `[l, r]` pairs. Return the total painted length.", "fr": "`segments` est une liste de paires `[l, r]`. Retourne la longueur totale peinte."}}' WHERE source = 'seed' AND test_set = 'covered-length';
UPDATE challenges SET signature = '{"read": [{"n": "n", "t": "int", "hide": true}, {"n": "meetings", "t": "int[][]", "len": "n", "cols": 2}], "args": ["meetings"], "ret": "int", "doc": {"en": "`meetings` is a list of `[start, end]` pairs. Return the minimum number of rooms.", "fr": "`meetings` est une liste de paires `[début, fin]`. Retourne le nombre minimum de salles."}}' WHERE source = 'seed' AND test_set = 'meeting-rooms';
UPDATE challenges SET signature = '{"read": [{"n": "rows", "t": "int", "hide": true}, {"n": "columns", "t": "int", "hide": true}, {"n": "grid", "t": "str[]", "len": "rows"}], "args": ["grid"], "ret": "int", "doc": {"en": "`grid` is a list of strings (one per row). Return the minimum number of moves from S to E, or -1.", "fr": "`grid` est une liste de chaînes (une par ligne). Retourne le nombre minimum de déplacements de S à E, ou -1."}}' WHERE source = 'seed' AND test_set = 'grid-escape';
UPDATE challenges SET signature = '{"read": [{"n": "n", "t": "int", "hide": true}, {"n": "x", "t": "int"}, {"n": "coins", "t": "int[]", "len": "n"}], "args": ["coins", "x"], "ret": "int", "doc": {"en": "`coins` is the list of coin values, `x` the amount. Return the number of ways, modulo 1 000 000 007.", "fr": "`coins` est la liste des pièces, `x` la somme. Retourne le nombre de façons, modulo 1 000 000 007."}}' WHERE source = 'seed' AND test_set = 'coin-combinations';
UPDATE challenges SET signature = '{"read": [{"n": "n", "t": "int", "hide": true}, {"n": "a", "t": "int[]", "len": "n"}], "args": ["a"], "ret": "int", "doc": {"en": "`a` is the list. Return the length of the longest strictly increasing subsequence.", "fr": "`a` est la liste. Retourne la longueur de la plus longue sous-suite strictement croissante."}}' WHERE source = 'seed' AND test_set = 'lis';
UPDATE challenges SET signature = '{"read": [{"n": "n", "t": "int", "hide": true}, {"n": "a", "t": "int[]", "len": "n"}], "args": ["a"], "ret": "int", "doc": {"en": "`a` is the list. Return the number of inversions (it can be larger than 2³¹: use 64-bit integers).", "fr": "`a` est la liste. Retourne le nombre d''inversions (il peut dépasser 2³¹ : utilise des entiers 64 bits)."}}' WHERE source = 'seed' AND test_set = 'inversions';
UPDATE challenges SET signature = '{"read": [{"n": "n", "t": "int"}, {"n": "m", "t": "int", "hide": true}, {"n": "roads", "t": "int[][]", "len": "m", "cols": 3}], "args": ["n", "roads"], "ret": "int", "doc": {"en": "`n` is the number of cities, `roads` a list of `[u, v, w]`. Return the cheapest total toll from 1 to n, or -1.", "fr": "`n` est le nombre de villes, `roads` une liste de `[u, v, w]`. Retourne le péage total minimum de 1 à n, ou -1."}}' WHERE source = 'seed' AND test_set = 'cheapest-route';
UPDATE challenges SET signature = '{"read": [{"n": "n", "t": "int", "hide": true}, {"n": "k", "t": "int"}, {"n": "a", "t": "int[]", "len": "n"}], "args": ["a", "k"], "ret": "int", "doc": {"en": "`a` is the list, `k` the window size. Return the sum of the maximums of all windows.", "fr": "`a` est la liste, `k` la taille de la fenêtre. Retourne la somme des maximums de toutes les fenêtres."}}' WHERE source = 'seed' AND test_set = 'window-max-sum';
UPDATE challenges SET signature = '{"read": [{"n": "n", "t": "int", "hide": true}, {"n": "heights", "t": "int[]", "len": "n"}], "args": ["heights"], "ret": "int", "doc": {"en": "`heights` is the list of heights. Return the largest rectangle area.", "fr": "`heights` est la liste des hauteurs. Retourne l''aire du plus grand rectangle."}}' WHERE source = 'seed' AND test_set = 'histogram';
UPDATE challenges SET signature = '{"read": [{"n": "s", "t": "str"}, {"n": "t", "t": "str"}], "args": ["s", "t"], "ret": "int", "doc": {"en": "`s` and `t` are the two words. Return the minimum number of operations.", "fr": "`s` et `t` sont les deux mots. Retourne le nombre minimum d''opérations."}}' WHERE source = 'seed' AND test_set = 'edit-distance';
